<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,api,loadWorkspaces,loadData,notify} from '../state'
const router=useRouter(),busy=ref(false),cases=ref<any[]>([])
const company=computed(()=>cases.value.find(c=>c.variant==='industrial')||cases.value[0])
onMounted(async()=>{try{cases.value=await api('/showcase/summary')}catch{}})
async function open(){if(state.user&&!state.user.is_guest){router.push(state.user.verified?'/overview':'/check-email');return}busy.value=true;try{const r=await api('/demo',{method:'POST',body:{variant:'industrial'}});sessionStorage.setItem('sd_tour','1');state.user=r.user;await loadWorkspaces(r.workspace_id);await loadData();router.push('/overview')}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
</script>
<template><div class="bank-preview-app"><header><div class="row gap-sm"><span class="bank-mark">A</span><strong>{{t('Alfa-Business','Альфа-Бизнес')}}</strong><span class="badge neutral">{{t('Integration preview','Точка интеграции')}}</span></div><RouterLink to="/login" class="btn secondary small-btn">{{t('Account / jury sign in','Вход в аккаунт / для жюри')}}</RouterLink></header><div class="bank-preview-layout"><aside><h4>{{company?.name||t('Company intelligence','Аналитика компании')}}</h4><button @click="open" :disabled="busy"><Icon name="Radar" :size="18"/>{{t('Business signals','Бизнес-сигналы')}}<span class="count-pill">{{company?.event_count??'—'}}</span></button><RouterLink to="/register" class="text-link mt-lg">{{t('Connect my company','Добавить свою компанию')}}</RouterLink><p>{{t('A persistent entry to business intelligence inside an internet bank.','Постоянная точка входа в бизнес-аналитику из интернет-банка.')}}</p></aside><main><span class="eyebrow">{{t('YOUR BUSINESS AT A GLANCE','ВАШ БИЗНЕС В ОБЗОРЕ')}}</span><h1>{{t('Good decisions start here.','Здесь начинаются обоснованные решения.')}}</h1><div class="notice"><Icon name="Info" :size="18"/>{{t('Bank interface integration preview. The signals below come from real collected reporting. No bank account or payment service is connected.','Точка интеграции с интерфейсом банка. Ниже — анализ реальных собранных материалов. Банковский счёт и платежи не подключены.')}}</div><section class="bank-entry-card"><div class="row between"><span class="eyebrow">{{t('NEWS & BUSINESS INTELLIGENCE','НОВОСТНАЯ БИЗНЕС-АНАЛИТИКА')}}</span><Icon name="Radar" :size="30"/></div><h2>{{t('What’s changing for your business?','Что меняется для вашего бизнеса?')}}</h2><p>{{t('Signals selected for company context, with source evidence, relevant bank research and a useful next move.','События для контекста компании: первоисточники, подходящие обзоры банка и полезный следующий шаг.')}}</p><div class="bank-preview-signals"><div v-for="e in company?.events||[]" :key="e.en.title"><span class="badge" :class="e.sentiment">{{e.relevance}}% {{t('relevance','релевантность')}}</span><strong>{{e[state.locale]?.title}}</strong><span>{{e[state.locale]?.why}}</span></div></div><p v-if="!company?.events?.length" class="muted">{{t('Connect your company to prepare your first verified signals.','Добавьте компанию, чтобы подготовить первые проверенные сигналы.')}}</p><button class="btn primary large-btn" @click="open" :disabled="busy"><Icon :name="busy?'LoaderCircle':'ArrowUpRight'" :class="{spin:busy}" :size="18"/>{{t('Open business intelligence','Открыть бизнес-аналитику')}}</button><span class="small muted">{{t('Read-only tour · sign in to run research','Гостевой просмотр · войдите для запуска анализа')}}</span></section></main></div></div></template>
